"""Public Unit 13 design inputs; no learner or answer-key prose."""
from pathlib import Path
import json

OUT = Path('curriculum/proposals/unit13')
OUT.mkdir(parents=True, exist_ok=True)
def save(name, value):
    (OUT / name).write_text(json.dumps(value, ensure_ascii=False, indent=2) + '\n', encoding='utf-8', newline='\n')

examples = [
('Se munuc hīerde ðone sang.', 'The monk heard the song.', 'Subject, finite verb and object in an ordinary main clause.'),
('Ðone sang hīerde se munuc.', 'The monk heard the song.', 'Fronted accusative object; case and agreement retain participant roles.'),
('Ðā hīerde se munuc ðone sang.', 'Then the monk heard the song.', 'Initial adverb and a following finite verb before a nominal subject.'),
('Ðā hē ðone sang hīerde, ðā ēode hē tō ðǣm bisceope.', 'When he heard the song, he went to the bishop.', 'Temporal conjunction and correlative adverb; dependent versus main-clause placement.'),
('Se sang wæs swēte. Hē wæs ēac wynsum.', 'The song was sweet. It was also pleasant.', 'Masculine personal reference to a grammatically masculine inanimate antecedent.'),
('Se bisceop geseah ðone munuc and grētte hine.', 'The bishop saw the monk and greeted him.', 'Continued subject through coordination; personal accusative retains the object.'),
('Se bisceop geseah ðone munuc. Hē wæs on ðǣm hūse.', 'The bishop saw the monk. He was in the house.', 'The second sentence can refer to either man in a suitable context; morphology alone does not select one.'),
('Se bisceop cwæð: “Ic wille mid ēow sprecan.”', 'The bishop said, “I want to speak with you.”', 'The bishop addresses several monks. Quoted person is interpreted from the speaker and addressees.'),
('Se munuc, ðe se bisceop grētte, ēode tō ðǣre cirican.', 'The monk whom the bishop greeted went to the church.', 'A nominative antecedent is the object within its relative clause.'),
('Ðā se bisceop cōm, ðā sungon ðā brōðor.', 'When the bishop came, the brothers sang.', 'Three identical surfaces serve as temporal conjunction, correlative adverb and article.'),
('Se bisceop wæs on ðǣm hūse, and se munuc on ðǣre cirican.', 'The bishop was in the house, and the monk in the church.', 'Recover the repeated copula in the coordinated clause with a different expressed subject.'),
('Hē sægde ðæt se sang swēte wǣre.', 'He said that the song was sweet.', 'Content-clause boundary and late finite subjunctive, with relative reporting time.')
]
public_examples = [dict(example_id=f'NEW-U13-EXAMPLE{i:02}', origin='new_teaching_material', text=t, translation=tr, target=target, graded=False) for i,(t,tr,target) in enumerate(examples,1)]
reading = ('Se bisceop sæt on ðǣm hūse, and se munuc wæs ðǣr. '
           'Ðā se munuc ðone sang hīerde, ðā ēode hē tō ðǣm bisceope. '
           'Se munuc cwæð: “Ic hīerde ðone sang, ðe swīðe wynsum wæs. Hīerdest ðū hine?” '
           'Se bisceop cwæð: “Gā nū, and lǣd ðā brōðor hider.” '
           'Ðā ēode se munuc tō ðǣre cirican, and cōm ęft mid ðǣm brōðrum. '
           'Se bisceop geseah hīe and cwæð: “Gē sindon mīne frīend. Ic wille mid ēow sprecan.” '
           'Se munuc sæt mid ðǣm brōðrum, and hīe hīerdon ðæs bisceopes word.')
save('composition-seed.json', dict(schema_version=1,chapter='ch13', status='public_design_pending_independent_evidence_reconciliation',
    teaching_examples=public_examples, new_reading=dict(span_id='NEW-U13-READING',title='The bishop and the monk',origin='new_teaching_material', text=reading, word_count=len(reading.split()),
    rationale='A complete hearing, inquiry, summons and gathering. Explicit nouns, masculine reference to song, relative-clause embedding, temporal correlation, omitted repeated subject and quoted speaker/addressees prepare the checked Chad passage. This is an original account, not an adaptation or purported historical event.')))

tasks=[]
def task(code, mode, prompt, target, texts=None, roles=None, outputs=None):
    tasks.append(dict(task_id='NEW-U13-'+code,key_id='KEY-NEW-U13-'+code,origin='new_teaching_material',mode=mode,prompt=prompt,target_specification=target,
                      input_texts=texts or [],feature_roles=roles or [], requested_outputs=outputs or [],local_support=[],dependency_status='pending_audit'))

task('F01','production_morphology','Give the complete nominative, genitive, dative and accusative singular and plural of mōdor, dohtor and brōðor. Explain the selected oblique and plural stems.','Complete kinship systems; no inference from the English singular.',roles=['kinship_systems'],outputs=[{'kind':'paradigm','lemma':x,'cases':['nominative','genitive','dative','accusative'],'numbers':['singular','plural']} for x in ['mōdor','dohtor','brōðor']])
task('F02','production_morphology','Give the complete nominative, genitive, dative and accusative singular and plural of æx and ēagðȳrel. Explain the retained stem in æx and the syncopated stem before endings in ēagðȳrel.','Complete long feminine and selected syncopating neuter systems; æx is not a new exceptional class.',roles=['nominal_systems'],outputs=[{'kind':'paradigm','lemma':x,'cases':['nominative','genitive','dative','accusative'],'numbers':['singular','plural']} for x in ['æx','ēagðȳrel']])
task('F03','production_morphology','Give the genitive and dative singular and the nominative and genitive plural of cirice, mynster and wyrttruma. State the model used for each.','Diagnose complete supporting noun systems through actual model and stem choices.',roles=['nominal_systems'],outputs=[{'kind':'form','lemma':x,'case':c,'number':n} for x in ['cirice','mynster','wyrttruma'] for c,n in [('genitive','singular'),('dative','singular'),('nominative','plural'),('genitive','plural')]])
task('F04','production_morphology','For swēte, give all strong nominative, genitive, dative and accusative singular and plural forms in all three genders. Then give the weak masculine nominative singular of its comparative and both strong and weak masculine nominative singular of its superlative. Explain the stems and endings.','Complete adjective family with comparison; distinct instrumental cells remain reference.',roles=['adjective_systems'],outputs=[{'kind':'paradigm','lemma':'swēte','declension':'strong','cases':['nominative','genitive','dative','accusative'],'numbers':['singular','plural'],'genders':['masculine','neuter','feminine']},{'kind':'comparison_diagnostics','positions':['comparative weak masculine nominative singular','superlative strong masculine nominative singular','superlative weak masculine nominative singular']}])
task('F05','production_morphology','Give the complete present and preterite indicative of forceorfan: all three persons in singular and plural. Using the printed principal parts, explain the present singular changes and the distribution of preterite stems.','Complete defined strong system, with supplied citation status distinguished from productive syntax.',roles=['verb_systems'],outputs=[{'kind':'paradigm','lemma':'forceorfan','tenses':['present','preterite'],'mood':'indicative','persons':[1,2,3],'numbers':['singular','plural']},{'kind':'explanation','positions':['present singular changes','preterite stem distribution'],'support':'printed principal parts remain visible'}])
task('F06','production_morphology','Give the singular and plural commands of winnan, begān and behealdan. For fordilgian and onlīesan, give the base present and past participles.','Complete assigned command pairs and participle bases; no unassigned adjective cells.',roles=['verb_systems'],outputs=[{'kind':'commands','lemmas':['winnan','begān','behealdan'],'numbers':['singular','plural']},{'kind':'participle_bases','lemmas':['fordilgian','onlīesan'],'types':['present','past']}])

task('A01','analysis','Translate both clauses. Identify the subject, direct object and finite verb in each; explain which forms settle the participants.','Case, not first position, identifies the object.',['Se bisceop grētte ðone munuc.','Ðone munuc grētte se bisceop.'],['clause_roles','fronting'],[{'kind':'translation','positions':[1,2]},{'kind':'role_labels','per_input':['subject','object','finite verb']},{'kind':'explanation','topic':'case evidence'}])
task('A02','analysis','Divide this sentence into clauses; identify each finite verb and its subject. Label every ðā, and translate the whole sentence.','Temporal correlation and article distinguished by actual function.',['Ðā se munuc cōm, ðā grētte se bisceop ðā brōðor.'],['clause_roles','correlation'],[{'kind':'clause_map','positions':['dependent','main']},{'kind':'token_roles','targets':['ðā#1','ðā#2','ðā#3']},{'kind':'translation','positions':[1]}])
task('A03','analysis','Translate. Identify the main finite verb and the relative-clause finite verb; give the relative antecedent and its role in each clause.','Embedding does not change the main clause subject; internal relative case differs from antecedent case.',['Se bisceop, ðe se munuc grētte, sæt on ðǣm hūse.'],['clause_roles','relative_reference'],[{'kind':'translation','positions':[1]},{'kind':'finite_verbs','positions':['main','relative']},{'kind':'relative_analysis','fields':['antecedent','main-clause case','relative function']}])
task('A04','analysis','Translate. Identify the person greeted, the person who gave the food, and the recipient. Explain the understood subject and the pronoun cases.','Coordination with a continuing subject and two distinct object roles.',['Se munuc grētte ðone bisceop and sealde him ðone męte.'],['coordination','reference'],[{'kind':'translation','positions':[1]},{'kind':'participant_map','roles':['greeter','person greeted','giver','recipient','thing given']},{'kind':'case_analysis','tokens':['him','męte']}])
task('A05','analysis','Translate the second sentence after each context. State the referent of hē in each; explain what morphology establishes and what the context establishes.','Grammatical gender permits inanimate reference; context identifies the antecedent.',['Se sang wæs swēte. Hē wæs wynsum.','Se bisceop cōm. Hē wæs on ðǣm hūse.'],['reference'],[{'kind':'translation','positions':[1,2]},{'kind':'reference','targets':['hē#1','hē#2']},{'kind':'explanation','topic':'gender versus contextual choice'}])
task('A06','analysis','Give both possible referents of hē in the second sentence. Is either one selected by gender and number alone? Rewrite that sentence twice, naming each possible subject explicitly.','Recognize real reference ambiguity rather than invent a nearest-noun rule.',['Se bisceop geseah ðone munuc. Hē sæt on ðǣm hūse.'],['reference','explicit_reference'],[{'kind':'reference_options','token':'hē','count':2},{'kind':'explanation','topic':'limits of morphology'},{'kind':'old_english_rewrites','count':2}])
task('A07','analysis','The monk addresses the bishop. Translate, and identify each speaker/addressee reference in the quotation.','Direct speech resets first and second person to its own setting.',['Se munuc cwæð: “Ic hīerde ðone sang. Hīerdest ðū hine?”'],['quoted_reference'],[{'kind':'translation','positions':[1]},{'kind':'reference','targets':['Ic','ðū','hine']}])
task('A08','analysis','Translate. Identify the content-clause boundary, its finite verb, and the antecedent of hē. The monk is reporting his own presence.','Context and reporting stance settle person; verb position is descriptive.',['Se munuc sægde ðæt hē on ðǣm hūse wǣre.'],['clause_roles','reported_reference'],[{'kind':'translation','positions':[1]},{'kind':'clause_analysis','fields':['content clause','finite verb','hē referent','report mood']}])
task('A09','analysis','Translate, restoring the omitted repeated predicate in English. Then write the second clause in Old English with that predicate expressed and agreeing with its own subject.','The lexical predicate is recoverable; an expressed finite copula must agree with the plural second subject in this bounded coordination frame.',['Se bisceop wæs on ðǣre cirican, and ðā brōðor on ðǣm hūse.'],['coordination'],[{'kind':'translation','positions':[1]},{'kind':'old_english_clause','count':1,'agreement':'plural second subject'}])
task('A10','analysis','Translate both sentences. Explain which clause each initial phrase belongs to and identify the finite verbs. Are initial words themselves a reliable way to decide who performs an action?','Distinguish a fronted phrase from a dependent clause, and keep its case relations.',['On ðǣm hūse sæt se munuc.','Ðā se munuc on ðǣm hūse sæt, ðā cōm se bisceop.'],['clause_roles','fronting','correlation'],[{'kind':'translation','positions':[1,2]},{'kind':'initial_constituents','count':2},{'kind':'finite_verbs','count':3},{'kind':'explanation','topic':'initial position and roles'}])
task('A11','analysis','Translate and draw the clause structure, using brackets or indentation. Identify the subject of every finite verb and the referent/function of ðe and ðā.','Follow embedding inside a temporal clause before returning to the main action.',['Ðā se munuc, ðe se bisceop grētte, cōm, ðā sungon ðā brōðor.'],['long_sentence','relative_reference','correlation'],[{'kind':'translation','positions':[1]},{'kind':'clause_map','count':3},{'kind':'finite_subjects','count':3},{'kind':'token_roles','targets':['ðe','ðā#1','ðā#2','ðā#3']}])
task('A12','analysis','A learner says: “Every main clause has the finite verb as its second word, and every dependent clause puts it last.” Explain two problems with this statement, referring to the chapter’s checked examples. Then explain why Cook 25.7 can nevertheless require a final verb as a particular exercise target.','Constituents differ from words; tendencies and source-specific controls differ from universal grammatical rules.',roles=['order_limits'],outputs=[{'kind':'explanation','positions':['constituents versus words','attested variation','specific Cook target']}])

